const $=id=>document.getElementById(id), clamp=(x,a,b)=>Math.max(a,Math.min(b,x)), fmt=(x,n=4)=>Number.isFinite(x)?(+x.toFixed(n)).toString():"—";
let n=3,m=2,mode="known",result=null;
let consumers=[],resources=[],C=[],K=[],Y=[];
const colors=["#376b95","#d86d5b","#4d8c8a","#c49a45","#73866b","#855c8d","#59a14f","#e15759","#76b7b2","#edc948"];
function defaults(){consumers=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:.05,m:.08}));resources=Array.from({length:m},(_,a)=>({name:`Resource ${a+1}`,r0:2,s:2,d:0}));C=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>+(0.65+.18*((i+a)%3)).toFixed(3)));K=Array.from({length:n},()=>Array(m).fill(.35));Y=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>+(0.45+.1*((i+2*a)%3)).toFixed(3)))}
function tableConsumer(arr=consumers,prefix="c"){return `<table><thead><tr><th>消费者</th><th>名称</th><th>N₀</th><th>m</th></tr></thead><tbody>${arr.map((q,i)=>`<tr><th>N${i+1}</th><td><input data-${prefix}="${i},name" value="${q.name}"></td><td><input type="number" data-${prefix}="${i},n0" value="${q.n0}" step=".01"></td><td><input type="number" data-${prefix}="${i},m" value="${q.m}" step=".01"></td></tr>`).join("")}</tbody></table>`}
function tableResource(){return `<table><thead><tr><th>资源</th><th>名称</th><th>R₀</th><th>S</th><th>D</th></tr></thead><tbody>${resources.map((q,a)=>`<tr><th>R${a+1}</th><td><input data-r="${a},name" value="${q.name}"></td><td><input type="number" data-r="${a},r0" value="${q.r0}" step=".1"></td><td><input type="number" data-r="${a},s" value="${q.s}" step=".1"></td><td><input type="number" data-r="${a},d" value="${q.d}" step=".01"></td></tr>`).join("")}</tbody></table>`}
function matrixHTML(A,key){return `<table class="matrix"><thead><tr><th>消费者↓ / 资源→</th>${resources.map((q,a)=>`<th>R${a+1}</th>`).join("")}</tr></thead><tbody>${A.map((row,i)=>`<tr><th>N${i+1}</th>${row.map((v,a)=>`<td><input type="number" data-${key}="${i},${a}" value="${v}" step=".01"></td>`).join("")}</tr>`).join("")}</tbody></table>`}
function render(){ $("consumerTable").innerHTML=tableConsumer();$("resourceTable").innerHTML=tableResource();$("cTable").innerHTML=matrixHTML(C,"cm");$("kTable").innerHTML=matrixHTML(K,"km");$("yTable").innerHTML=matrixHTML(Y,"ym");renderDist();renderKnownDist();}
function sync(){document.querySelectorAll("[data-c]").forEach(e=>{let[i,k]=e.dataset.c.split(",");consumers[i][k]=k==="name"?e.value:+e.value});document.querySelectorAll("[data-r]").forEach(e=>{let[a,k]=e.dataset.r.split(",");resources[a][k]=k==="name"?e.value:+e.value});[["cm",C],["km",K],["ym",Y]].forEach(([key,A])=>document.querySelectorAll(`[data-${key}]`).forEach(e=>{let[i,a]=e.dataset[key].split(",");A[i][a]=+e.value}))}
function validate(sp=consumers,rs=resources,c=C,k=K,y=Y){sp.forEach((q,i)=>{if(!(q.n0>=0&&q.m>=0))throw Error(`消费者 N${i+1} 的 N₀、m 必须非负`)});rs.forEach((q,a)=>{if(!(q.r0>=0&&q.s>=0&&q.d>=0))throw Error(`资源 R${a+1} 的 R₀、S、D 必须非负`)});[c,k,y].forEach((A,z)=>A.forEach((row,i)=>row.forEach((v,a)=>{if(!(v>=0)||!Number.isFinite(v))throw Error(`${["c","K","Y"][z]}[${i+1},${a+1}] 必须为非负数`)})))}
function deriv(state,sp=consumers,rs=resources,c=C,k=K,y=Y){const nn=sp.length,mm=rs.length,linear=$("responseType")?.value==="linear";let ns=state.slice(0,nn),rr=state.slice(nn,nn+mm),dn=Array(nn).fill(0),dr=Array(mm).fill(0);for(let i=0;i<nn;i++){let growth=-sp[i].m;for(let a=0;a<mm;a++){let u=c[i][a]*(linear?rr[a]:rr[a]/Math.max(1e-12,k[i][a]+rr[a]));growth+=y[i][a]*u}dn[i]=ns[i]*growth}for(let a=0;a<mm;a++){dr[a]=rs[a].d*(rs[a].s-rr[a]);for(let i=0;i<nn;i++)dr[a]-=c[i][a]*ns[i]*(linear?rr[a]:rr[a]/Math.max(1e-12,k[i][a]+rr[a]))}return dn.concat(dr)}
function runModel(sp=consumers,rs=resources,c=C,k=K,y=Y){validate(sp,rs,c,k,y);let tm=Math.max(.1,+$("tMax").value),sample=Math.max(.01,+$("sample").value),h=Math.max(.0005,Math.min(.03,sample/6,tm/5000)),state=sp.map(q=>q.n0).concat(rs.map(q=>q.r0)),t=0,next=sample,pts=[{t:0,v:state.slice()}],stableStart=null,stable=null,window=Math.max(sample*3,tm*.08);while(t<tm-1e-10){let dt=Math.min(h,tm-t),f=z=>deriv(z,sp,rs,c,k,y),k1=f(state),k2=f(state.map((v,j)=>v+dt*k1[j]/2)),k3=f(state.map((v,j)=>v+dt*k2[j]/2)),k4=f(state.map((v,j)=>v+dt*k3[j]));state=state.map((v,j)=>Math.max(0,v+dt*(k1[j]+2*k2[j]+2*k3[j]+k4[j])/6));t+=dt;if(state.some(v=>!Number.isFinite(v)||v>1e9))throw Error("数值发散：请检查参数和单位");let d=f(state),rel=Math.max(...d.map(Math.abs))/Math.max(1,...state);if(rel<1e-7){if(stableStart===null)stableStart=t;if(stable===null&&t-stableStart>=window)stable=stableStart}else stableStart=null;if(t+1e-8>=next||t+1e-8>=tm){pts.push({t:Math.min(t,tm),v:state.slice()});next+=sample}}return{pts,stable,sp:sp.map(q=>({...q})),rs:rs.map(q=>({...q})),c:c.map(r=>r.slice()),k:k.map(r=>r.slice()),y:y.map(r=>r.slice())}}
function simulate(){sync();result=runModel();drawAll();setStatus("模拟完成")}
function axes(ctx,W,H,maxT,maxV){let p={l:50,r:12,t:10,b:32};ctx.clearRect(0,0,W,H);ctx.font="10px Arial";ctx.fillStyle="#666";ctx.strokeStyle="#ddd6ca";for(let z=0;z<5;z++){let v=maxV*z/4,y=H-p.b-v/maxV*(H-p.t-p.b);ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(W-p.r,y);ctx.stroke();ctx.fillText(fmt(v,2),4,y+3)}for(let z=0;z<6;z++){let t=maxT*z/5,x=p.l+t/maxT*(W-p.l-p.r);ctx.fillText(fmt(t,1),x-7,H-10)}ctx.setLineDash([]);return{X:t=>p.l+t/maxT*(W-p.l-p.r),Y:v=>H-p.b-v/maxV*(H-p.t-p.b)}}
function lineChart(id,offset,count,names){let c=$(id),ctx=c.getContext("2d"),last=result.pts.at(-1),maxT=Math.max(1,last.t),maxV=Math.max(.01,...result.pts.flatMap(q=>q.v.slice(offset,offset+count)))*1.08,a=axes(ctx,c.width,c.height,maxT,maxV);for(let j=0;j<count;j++){ctx.strokeStyle=colors[j%colors.length];ctx.lineWidth=2.2;ctx.beginPath();result.pts.forEach((q,z)=>z?ctx.lineTo(a.X(q.t),a.Y(q.v[offset+j])):ctx.moveTo(a.X(q.t),a.Y(q.v[offset+j])));ctx.stroke()}$(id==="nChart"?"nLegend":"rLegend").innerHTML=names.map((q,j)=>`<span><i style="background:${colors[j%colors.length]}"></i>${q}</span>`).join("")}
function drawAll(){const nn=result.sp.length,mm=result.rs.length;lineChart("nChart",0,nn,result.sp.map(q=>q.name));lineChart("rChart",nn,mm,result.rs.map(q=>q.name));let end=result.pts.at(-1).v;$("totalN").textContent=fmt(end.slice(0,nn).reduce((a,b)=>a+b,0),4);$("stable").textContent=result.stable==null?"未达到":fmt(result.stable,2)+" h"}
function resize(){sync();n=clamp(Math.round(+$("nN").value||3),1,20);m=clamp(Math.round(+$("nM").value||2),1,30);$("nN").value=n;$("nM").value=m;defaults();result=null;render();setStatus(`已建立 ${n} 个消费者 × ${m} 种资源`)}
function setMode(x){sync();mode=x;["known","monte"].forEach(q=>{$(q+"Panel").classList.toggle("hidden",q!==x);$(q+"Tab").classList.toggle("active",q===x)});$("modeTitle").textContent=x==="known"?"已知参数设置":"多次随机模拟参数设置";$("runBtn").classList.toggle("hidden",x==="monte");$("exportBtn").classList.toggle("hidden",x==="monte")}
function setStatus(s,bad=false){$("status").textContent=s;$("status").style.color=bad?"#a54e44":""}
const distMeta=[
 ["N₀","n0","lognormal",.05,.4,.001,.5,"消费者初始生物量"],["m","mort","normal",.08,.03,0,.4,"维持/死亡率"],["R₀","r0","uniform",2,.5,.2,4,"资源初始浓度"],["S","supply","uniform",2,.5,.2,4,"外源供给目标浓度"],["D","dilution","fixed",0,0,0,.5,"资源周转/补给率"],["cᵢα","uptake","lognormal",.8,.35,.01,3,"最大摄取率"],["Kᵢα","half","lognormal",.35,.25,.01,2,"半饱和常数"],["Yᵢα","yield","normal",.55,.15,.05,1.5,"生物量产率"]];
function updateDistRow(row,prefix){const dist=row.querySelector(`[data-${prefix}="dist"]`).value,enabled=dist==="fixed"?["mu"]:dist==="uniform"?["lo","hi"]:["mu","sd","lo","hi"];["mu","sd","lo","hi"].forEach(k=>{const input=row.querySelector(`[data-${prefix}="${k}"]`),on=enabled.includes(k);input.disabled=!on;input.closest("td").classList.toggle("is-disabled",!on)})}
function updateAllDistRows(){document.querySelectorAll("#distRows tr").forEach(row=>updateDistRow(row,"d"));document.querySelectorAll("#knownDistRows tr").forEach(row=>updateDistRow(row,"kd"))}
function renderDist(){if(!$("distRows"))return;$("distRows").innerHTML=distMeta.map(q=>`<tr data-row="${q[1]}"><th>${q[0]}</th><td><select data-d="dist"><option value="fixed" ${q[2]==="fixed"?"selected":""}>固定值</option><option value="uniform" ${q[2]==="uniform"?"selected":""}>均匀分布</option><option value="normal" ${q[2]==="normal"?"selected":""}>截断正态</option><option value="lognormal" ${q[2]==="lognormal"?"selected":""}>截断对数正态</option></select></td><td><input data-d="mu" type="number" value="${q[3]}"></td><td><input data-d="sd" type="number" value="${q[4]}"></td><td><input data-d="lo" type="number" value="${q[5]}"></td><td><input data-d="hi" type="number" value="${q[6]}"></td><td>${q[7]}</td></tr>`).join("");updateAllDistRows()}
function renderKnownDist(){if(!$("knownDistRows"))return;$("knownDistRows").innerHTML=distMeta.map(q=>`<tr data-krow="${q[1]}"><th>${q[0]}</th><td><select data-kd="dist"><option value="fixed" ${q[2]==="fixed"?"selected":""}>固定值</option><option value="uniform" ${q[2]==="uniform"?"selected":""}>均匀分布</option><option value="normal" ${q[2]==="normal"?"selected":""}>截断正态</option><option value="lognormal" ${q[2]==="lognormal"?"selected":""}>截断对数正态</option></select></td><td><input data-kd="mu" type="number" value="${q[3]}"></td><td><input data-kd="sd" type="number" value="${q[4]}"></td><td><input data-kd="lo" type="number" value="${q[5]}"></td><td><input data-kd="hi" type="number" value="${q[6]}"></td><td>${q[7]}</td></tr>`).join("");updateAllDistRows()}
function gauss(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function sampleCfg(q){let row=document.querySelector(`[data-row="${q[1]}"]`),get=k=>row.querySelector(`[data-d="${k}"]`),dist=get("dist").value,mu=+get("mu").value,sd=Math.max(0,+get("sd").value),lo=+get("lo").value,hi=+get("hi").value;if(!(lo<=hi))throw Error(`${q[0]} 的下限不能大于上限`);let draw=()=>dist==="fixed"?mu:dist==="uniform"?lo+Math.random()*(hi-lo):dist==="normal"?mu+sd*gauss():Math.exp(Math.log(Math.max(mu,1e-12))+sd*gauss());for(let z=0;z<100;z++){let x=draw();if(x>=lo&&x<=hi)return x}return clamp(draw(),lo,hi)}
function sampleKnownCfg(q){let row=document.querySelector(`[data-krow="${q[1]}"]`),get=k=>row.querySelector(`[data-kd="${k}"]`),dist=get("dist").value,mu=+get("mu").value,sd=Math.max(0,+get("sd").value),lo=+get("lo").value,hi=+get("hi").value;if(!(lo<=hi))throw Error(`${q[0]} 的下限不能大于上限`);let draw=()=>dist==="fixed"?mu:dist==="uniform"?lo+Math.random()*(hi-lo):dist==="normal"?mu+sd*gauss():Math.exp(Math.log(Math.max(mu,1e-12))+sd*gauss());for(let z=0;z<100;z++){let x=draw();if(Number.isFinite(x)&&x>=lo&&x<=hi)return x}return clamp(draw(),lo,hi)}
function generateKnown(){const cfg=Object.fromEntries(distMeta.map(q=>[q[1],()=>sampleKnownCfg(q)]));consumers=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:cfg.n0(),m:cfg.mort()}));resources=Array.from({length:m},(_,a)=>({name:`Resource ${a+1}`,r0:cfg.r0(),s:cfg.supply(),d:cfg.dilution()}));C=Array.from({length:n},()=>Array.from({length:m},()=>cfg.uptake()));K=Array.from({length:n},()=>Array.from({length:m},()=>cfg.half()));Y=Array.from({length:n},()=>Array.from({length:m},()=>cfg.yield()));validate();$("consumerTable").innerHTML=tableConsumer();$("resourceTable").innerHTML=tableResource();$("cTable").innerHTML=matrixHTML(C,"cm");$("kTable").innerHTML=matrixHTML(K,"km");$("yTable").innerHTML=matrixHTML(Y,"ym");result=null;setStatus(`已为 ${n} 个消费者 × ${m} 种资源生成参数`)}
function randomModel(){let cfg=Object.fromEntries(distMeta.map(q=>[q[1],()=>sampleCfg(q)])),sp=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:cfg.n0(),m:cfg.mort()})),rs=Array.from({length:m},(_,a)=>({name:`Resource ${a+1}`,r0:cfg.r0(),s:cfg.supply(),d:cfg.dilution()})),c=Array.from({length:n},()=>Array.from({length:m},()=>cfg.uptake())),k=Array.from({length:n},()=>Array.from({length:m},()=>cfg.half())),y=Array.from({length:n},()=>Array.from({length:m},()=>cfg.yield()));return{sp,rs,c,k,y}}
function csvCell(x){let s=String(x??"");return /[",\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s}
async function saveCSV(text,name){let blob=new Blob(["\ufeff"+text],{type:"text/csv;charset=utf-8"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},1000)}
function params(res){let p=[["response_type",$("responseType")?.value||"monod"]];res.sp.forEach((q,i)=>p.push([`N${i+1}_name`,q.name],[`N${i+1}_N0`,q.n0],[`N${i+1}_m`,q.m]));res.rs.forEach((q,a)=>p.push([`R${a+1}_name`,q.name],[`R${a+1}_R0`,q.r0],[`R${a+1}_S`,q.s],[`R${a+1}_D`,q.d]));for(let i=0;i<res.sp.length;i++)for(let a=0;a<res.rs.length;a++)p.push([`c_${i+1}_${a+1}`,res.c[i][a]],[`K_${i+1}_${a+1}`,res.k[i][a]],[`Y_${i+1}_${a+1}`,res.y[i][a]]);return p}
function rowsFor(rec,run){const nn=rec.sp.length,mm=rec.rs.length,p=params(rec),head=["run","stable_time","time",...Array.from({length:nn},(_,i)=>`N${i+1}`),...Array.from({length:mm},(_,a)=>`R${a+1}`),...p.map(x=>x[0])],rows=rec.pts.map(q=>[run,rec.stable??"",q.t,...q.v,...p.map(x=>x[1])]);return{head,rows}}
async function exportCSV(){if(!result)simulate();let x=rowsFor(result,1),stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19);await saveCSV([x.head,...x.rows].map(r=>r.map(csvCell).join(",")).join("\n"),`consumer_resource_single_${stamp}.csv`);setStatus("单次模拟 CSV 已生成")}
async function batch(){let count=clamp(Math.round(+$("batchCount").value||50),2,1000),all=[],head=null,btn=$("batchBtn");btn.disabled=true;try{for(let run=1;run<=count;run++){let z=randomModel(),rec=runModel(z.sp,z.rs,z.c,z.k,z.y),x=rowsFor(rec,run);head??=x.head;all.push(...x.rows);$("progress").style.width=run/count*100+"%";$("batchInfo").textContent=`正在模拟 ${run} / ${count}`;if(run%5===0)await new Promise(r=>setTimeout(r,0))}let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19);await saveCSV([head,...all].map(r=>r.map(csvCell).join(",")).join("\n"),`consumer_resource_random_${count}_${stamp}.csv`);$("batchInfo").textContent=`完成 ${count} 次模拟，CSV 已生成`;setStatus("多次随机模拟完成")}finally{btn.disabled=false}}
function parseTargets(text,max,label){text=String(text).trim();if(!text||/^(全部|all|\*)$/i.test(text))return Array.from({length:max},(_,i)=>i);let out=new Set();for(const part of text.split(/[,，\s]+/).filter(Boolean)){let m=part.match(/^(\d+)(?:-(\d+))?$/);if(!m)throw Error(`${label}编号格式错误：${part}`);let a=+m[1],b=+(m[2]||m[1]);if(a>b)[a,b]=[b,a];for(let x=a;x<=b;x++){if(x<1||x>max)throw Error(`${label}编号 ${x} 超出 1–${max}`);out.add(x-1)}}if(!out.size)throw Error(`请至少选择一个${label}`);return [...out]}
function applyBulk(){sync();let key=$("bulkParam").value,value=+$("bulkValue").value;if(!Number.isFinite(value)||value<0)throw Error("统一数值必须是非负数");let ii=parseTargets($("bulkConsumers").value,n,"消费者"),aa=parseTargets($("bulkResources").value,m,"资源");if(key==="n0")ii.forEach(i=>consumers[i].n0=value);else if(key==="mort")ii.forEach(i=>consumers[i].m=value);else if(key==="r0")aa.forEach(a=>resources[a].r0=value);else if(key==="supply")aa.forEach(a=>resources[a].s=value);else if(key==="dilution")aa.forEach(a=>resources[a].d=value);else{let A=key==="uptake"?C:key==="half"?K:Y;ii.forEach(i=>aa.forEach(a=>A[i][a]=value))}validate();$("consumerTable").innerHTML=tableConsumer();$("resourceTable").innerHTML=tableResource();$("cTable").innerHTML=matrixHTML(C,"cm");$("kTable").innerHTML=matrixHTML(K,"km");$("yTable").innerHTML=matrixHTML(Y,"ym");result=null;setStatus(`已将所选 ${key} 同时设为 ${value}`)}
function safe(fn){try{let x=fn();if(x&&x.catch)x.catch(e=>{if(e.name!=="AbortError")setStatus(e.message,true)})}catch(e){setStatus(e.message,true)}}
document.addEventListener("change",e=>{if(e.target.matches('[data-d="dist"]'))updateDistRow(e.target.closest("tr"),"d");if(e.target.matches('[data-kd="dist"]'))updateDistRow(e.target.closest("tr"),"kd")});$("knownTab").onclick=()=>safe(()=>setMode("known"));$("monteTab").onclick=()=>safe(()=>setMode("monte"));$("resizeBtn").onclick=()=>safe(resize);$("runBtn").onclick=()=>safe(simulate);$("exportBtn").onclick=()=>safe(exportCSV);$("batchBtn").onclick=()=>safe(batch);$("generateKnownBtn").onclick=()=>safe(generateKnown);$("bulkApplyBtn").onclick=()=>safe(applyBulk);$("responseType").onchange=()=>{result=null;setStatus("资源响应形式已更改，请重新运行模拟")};defaults();render();simulate();

